// Material Symbols Outlined, weight 200, 24px (google/material-design-icons).
private fun slim(name: String, pathData: String): ImageVector =
    ImageVector.Builder(name, 24.dp, 24.dp, 960f, 960f).apply {
        addGroup(translationY = 960f)
        addPath(PathParser().parsePathString(pathData).toNodes(), fill = SolidColor(Color.Black))
        clearGroup()
    }.build()

